/* =========================================================
   E.G.Light / Elsewedy — Offline File Archive
   Single-file Phase 1 prototype
   ========================================================= */
const LOGO =
  "data:image/png;base64,";
const DB_NAME = "eglight_archive_v1",
  DB_VER = 1;
const PERMISSIONS = [
  "dashboard.view",
  "archive.view",
  "archive.create",
  "archive.rename",
  "archive.delete",
  "archive.upload",
  "archive.download",
  "archive.move",
  "search.view",
  "users.view",
  "users.create",
  "users.edit",
  "users.delete",
  "permissions.view",
  "permissions.edit",
  "logs.view",
  "settings.view",
  "settings.edit",
  "profile.view",
];
const DEFAULT_PERMS = [
  "dashboard.view",
  "archive.view",
  "archive.upload",
  "archive.download",
  "search.view",
  "profile.view",
];
const state = {
  user: null,
  screen: "dashboard",
  db: null,
  rootHandle: null,
  tree: null,
  currentNode: null,
  view: "list",
  query: "",
  filterType: "all",
  loading: false,
  users: [],
  logs: [],
  settings: { theme: "light", sidebar: false },
};

function $(s) {
  return document.querySelector(s);
}
function esc(v) {
  return String(v ?? "").replace(
    /[&<>"']/g,
    (m) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        m
      ],
  );
}
function uid(prefix = "ID") {
  return (
    prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 7)
  );
}
function fmtSize(n) {
  if (n < 1024) return n + " B";
  let u = ["KB", "MB", "GB", "TB"],
    i = -1;
  do {
    n /= 1024;
    i++;
  } while (n >= 1024 && i < u.length - 1);
  return n.toFixed(n < 10 ? 1 : 0) + " " + u[i];
}
function fmtDate(d) {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(d));
}
function ext(name) {
  let x = name.lastIndexOf(".");
  return x > -1 ? name.slice(x + 1).toLowerCase() : "";
}
function fileIcon(name) {
  let e = ext(name);
  return e === "pdf"
    ? "📕"
    : ["doc", "docx"].includes(e)
      ? "📘"
      : ["xls", "xlsx", "csv"].includes(e)
        ? "📗"
        : ["jpg", "jpeg", "png", "gif", "webp", "svg"].includes(e)
          ? "🖼️"
          : e === "txt" || e === "md"
            ? "📄"
            : "📦";
}
function hasPermission(p) {
  return state.user?.role === "admin" || state.user?.permissions?.includes(p);
}
function canScreen(screen) {
  const p = {
    dashboard: "dashboard.view",
    archive: "archive.view",
    search: "search.view",
    users: "users.view",
    permissions: "permissions.view",
    logs: "logs.view",
    settings: "settings.view",
    profile: "profile.view",
  }[screen];
  return hasPermission(p);
}
function toast(msg, type = "ok") {
  const el = document.createElement("div");
  el.className = "toast " + (type === "err" ? "err" : "ok");
  el.textContent = msg;
  $("#toastRoot").appendChild(el);
  setTimeout(() => el.remove(), 3000);
}
function modal(html) {
  $("#modalRoot").innerHTML =
    '<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal">' +
    html +
    "</div></div>";
}
function closeModal() {
  $("#modalRoot").innerHTML = "";
}

function openDB() {
  return new Promise((res, rej) => {
    const r = indexedDB.open(DB_NAME, DB_VER);
    r.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains("users"))
        db.createObjectStore("users", { keyPath: "id" });
      if (!db.objectStoreNames.contains("logs"))
        db.createObjectStore("logs", { keyPath: "id" });
      if (!db.objectStoreNames.contains("settings"))
        db.createObjectStore("settings", { keyPath: "key" });
    };
    r.onsuccess = (e) => {
      state.db = e.target.result;
      res(state.db);
    };
    r.onerror = () => rej(r.error);
  });
}
function tx(store, mode = "readonly") {
  return state.db.transaction(store, mode).objectStore(store);
}
function getAll(store) {
  return new Promise((res, rej) => {
    let r = tx(store).getAll();
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}
function put(store, val) {
  return new Promise((res, rej) => {
    let r = tx(store, "readwrite").put(val);
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}
function del(store, id) {
  return new Promise((res, rej) => {
    let r = tx(store, "readwrite").delete(id);
    r.onsuccess = () => res();
    r.onerror = () => rej(r.error);
  });
}
async function initDB() {
  await openDB();
  state.users = await getAll("users");
  state.logs = await getAll("logs");
  if (!state.users.length) {
    const admin = {
      id: uid("USR"),
      name: "System Administrator",
      username: "admin",
      password: "admin123",
      role: "admin",
      status: "active",
      permissions: [...PERMISSIONS],
    };
    await put("users", admin);
    state.users = [admin];
  }
}
async function logAction(action, target = "") {
  const l = {
    id: uid("LOG"),
    user: state.user?.username || "system",
    date: Date.now(),
    action,
    target,
  };
  await put("logs", l);
  state.logs.unshift(l);
  state.logs = state.logs.slice(0, 1000);
}

function loginPage() {
  $("#app").innerHTML =
    `<div class="login-wrap"><div class="login-card"><div class="brand"><img src="${LOGO}" alt="E.G.Light"><h1>File Archive System</h1><p>Offline Enterprise File Archive</p></div>
 <form onsubmit="doLogin(event)"><div class="field"><label>Username / Employee ID</label><input id="loginUser" autocomplete="username" placeholder="Enter Username" required></div>
 <div class="field"><label>Password</label><div class="password-box"><input id="loginPass" type="password" autocomplete="current-password" placeholder="Enter Password" required><button class="eye" type="button" onclick="togglePass()">◉</button></div></div>
 <div class="row"><label class="remember"><input id="remember" type="checkbox"> Remember Me</label><span class="muted" style="font-size:12px">Offline prototype</span></div>
 <button class="primary" style="width:100%;margin-top:18px" id="loginBtn">LOGIN</button><div id="loginErr"></div></form>
 <div style="margin-top:18px;font-size:12px;color:#9ca3af;text-align:center">Phase 1 local authentication • Chrome / Edge recommended</div></div></div>`;
}
function togglePass() {
  const x = $("#loginPass");
  x.type = x.type === "password" ? "text" : "password";
}
async function doLogin(e) {
  e.preventDefault();
  const b = $("#loginBtn");
  b.disabled = true;
  b.textContent = "Loading…";
  $("#loginErr").innerHTML = "";
  const u = state.users.find(
    (x) =>
      x.username.toLowerCase() === $("#loginUser").value.trim().toLowerCase() &&
      x.status === "active" &&
      x.password === $("#loginPass").value,
  );
  if (!u) {
    $("#loginErr").innerHTML =
      '<div class="error">Invalid Login or disabled user.</div>';
    b.disabled = false;
    b.textContent = "LOGIN";
    return;
  }
  state.user = u;
  await logAction("Logged in");
  localStorage.setItem("eg_last_user", u.username);
  renderApp();
}
function logout() {
  state.user = null;
  state.rootHandle = null;
  localStorage.removeItem("eg_session");
  loginPage();
}

function navItems() {
  return [
    ["dashboard", "▦", "Dashboard", "dashboard.view"],
    ["archive", "🗂", "File Archive", "archive.view"],
    ["search", "⌕", "Search", "search.view"],
    ["users", "♙", "Users", "users.view"],
    ["permissions", "✓", "Permissions", "permissions.view"],
    ["logs", "☷", "Activity Logs", "logs.view"],
    ["settings", "⚙", "Settings", "settings.view"],
    ["profile", "●", "Profile", "profile.view"],
  ].filter((x) => hasPermission(x[3]));
}
function renderApp() {
  const collapsed = state.settings.sidebar;
  $("#app").innerHTML =
    `<div class="app-shell"><aside class="sidebar ${collapsed ? "collapsed" : ""}" id="sidebar">
 <div class="side-brand"><img src="${LOGO}" alt=""><strong>E.G.Light<br><small class="muted">File Archive</small></strong></div>
 <nav class="nav">${navItems()
   .map(
     (x) =>
       `<button class="${state.screen === x[0] ? "active" : ""}" onclick="go('${x[0]}')"><span class="ico">${x[1]}</span><span>${x[2]}</span></button>`,
   )
   .join("")}</nav>
 <button class="secondary logout" onclick="logout()">↪ <span>Logout</span></button></aside>
 <main class="main"><header class="topbar"><button class="icon-btn" onclick="toggleSidebar()">☰</button><div class="search"><input placeholder="Search archive…" value="${esc(state.query)}" onkeydown="if(event.key==='Enter'){state.query=this.value;go('search')}"></div><button class="icon-btn" onclick="toast('Notifications: no new alerts')">🔔</button>
 <div class="user-pill"><div class="avatar">${esc((state.user.name || "U")[0].toUpperCase())}</div><div><b>${esc(state.user.name)}</b><div class="muted">${esc(state.user.role)}</div></div></div></header><section class="content" id="content"></section></main></div>`;
  renderScreen();
}
function toggleSidebar() {
  state.settings.sidebar = !state.settings.sidebar;
  renderApp();
}
function go(s) {
  if (!canScreen(s)) {
    toast("Access denied", "err");
    return;
  }
  state.screen = s;
  renderApp();
}
function title(t, actions = "") {
  return `<div class="page-title"><div><h2>${t}</h2><div class="muted" style="margin-top:5px">E.G.Light / Elsewedy • Offline Mode</div></div><div class="actions">${actions}</div></div>`;
}

async function renderScreen() {
  const c = $("#content");
  if (!c) return;
  if (state.screen === "dashboard") return dashboard(c);
  if (state.screen === "archive") return archive(c);
  if (state.screen === "search") return searchPage(c);
  if (state.screen === "users") return usersPage(c);
  if (state.screen === "permissions") return permissionsPage(c);
  if (state.screen === "logs") return logsPage(c);
  if (state.screen === "settings") return settingsPage(c);
  if (state.screen === "profile") return profilePage(c);
}

function dashboard(c) {
  const files = countFiles(state.tree),
    folders = countFolders(state.tree),
    active = state.users.filter((u) => u.status === "active").length;
  c.innerHTML =
    title(
      "Admin Dashboard",
      state.user.role === "admin"
        ? '<button class="primary" onclick="openUserModal()">＋ Add User</button>'
        : "",
    ) +
    `
 <div class="cards"><div class="stat"><div class="k">TOTAL USERS</div><div class="v">${state.users.length}</div></div><div class="stat"><div class="k">TOTAL FILES</div><div class="v">${files}</div></div><div class="stat"><div class="k">TOTAL FOLDERS</div><div class="v">${folders}</div></div><div class="stat"><div class="k">ACTIVE USERS</div><div class="v">${active}</div></div></div>
 <div class="grid2"><div class="panel"><div class="panel-head"><h3>Recent Activities</h3><button class="secondary" onclick="go('logs')">View all</button></div><div class="panel-body"><div class="activity">${
   state.logs
     .slice(0, 7)
     .map(
       (l) =>
         `<div class="activity-item"><i class="dot"></i><div><b>${esc(l.user)}</b> ${esc(l.action)} ${l.target ? `<span class="muted">• ${esc(l.target)}</span>` : ""}<div class="muted" style="font-size:11px;margin-top:3px">${fmtDate(l.date)}</div></div></div>`,
     )
     .join("") || '<div class="empty">No activity yet.</div>'
 }</div></div></div>
 <div class="panel"><div class="panel-head"><h3>Archive</h3></div><div class="panel-body"><div style="font-size:14px;margin-bottom:8px">Local archive status</div>${state.tree ? `<div class="success">✓ ${esc(state.tree.name)} is loaded</div><div class="muted" style="margin-top:7px">${folders} folders • ${files} files</div>` : `<div class="muted">No archive folder selected.</div>`}<button class="primary" style="margin-top:16px" onclick="go('archive')">Open File Archive</button></div></div></div>`;
}
function countFiles(n) {
  if (!n) return 0;
  return (
    (n.files?.length || 0) +
    (n.children || []).reduce((a, x) => a + countFiles(x), 0)
  );
}
function countFolders(n) {
  if (!n) return 0;
  return 1 + (n.children || []).reduce((a, x) => a + countFolders(x), 0);
}

async function selectArchive() {
  if (!window.showDirectoryPicker) {
    toast("This browser does not support File System Access API", "err");
    return;
  }
  try {
    state.rootHandle = await window.showDirectoryPicker({ mode: "readwrite" });
    await logAction("Selected archive folder", state.rootHandle.name);
    state.loading = true;
    renderScreen();
    state.tree = await scanDir(state.rootHandle);
    state.currentNode = state.tree;
    state.loading = false;
    await logAction("Scanned archive", state.tree.name);
    renderScreen();
    toast("Archive loaded successfully");
  } catch (e) {
    state.loading = false;
    renderScreen();
    if (e.name !== "AbortError")
      toast("We don't have permission to access this folder.", "err");
  }
}
async function scanDir(handle) {
  const node = {
    id: uid("F"),
    name: handle.name,
    kind: "folder",
    handle,
    children: [],
    files: [],
    parent: null,
  };
  for await (const [name, h] of handle.entries()) {
    if (h.kind === "directory") {
      const ch = await scanDir(h);
      ch.parent = node;
      node.children.push(ch);
    } else
      node.files.push({
        id: uid("X"),
        name,
        kind: "file",
        handle: h,
        parent: node,
      });
  }
  node.children.sort((a, b) => a.name.localeCompare(b.name));
  node.files.sort((a, b) => a.name.localeCompare(b.name));
  return node;
}
function nodePath(n) {
  let a = [];
  while (n) {
    a.unshift(n);
    n = n.parent;
  }
  return a;
}
function renderTree(n) {
  return `<div class="tree-node"><div class="tree-row ${state.currentNode === n ? "selected" : ""}" onclick="selectNode('${n.id}')"><span class="caret">${n.children.length ? "▸" : ""}</span><span class="folder">📁</span><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(n.name)}</span></div>${n.children.length ? `<div class="children">${n.children.map(renderTree).join("")}</div>` : ""}</div>`;
}
function findNode(n, id) {
  if (n.id === id) return n;
  for (const c of n.children || []) {
    const x = findNode(c, id);
    if (x) return x;
  }
  return null;
}
function selectNode(id) {
  const n = findNode(state.tree, id);
  if (n) {
    state.currentNode = n;
    renderScreen();
  }
}
function archive(c) {
  const actions = `<button class="secondary" onclick="selectArchive()">📂 Select Archive Folder</button>${state.currentNode && hasPermission("archive.create") ? `<button class="primary" onclick="newFolder()">＋ New Folder</button>` : ""}`;
  if (state.loading) {
    c.innerHTML =
      title("File Archive") +
      `<div class="panel loading"><b>Loading Archive…</b><div style="width:min(500px,90%);text-align:center"><div class="progress"><i></i></div><div style="margin-top:8px">Scanning files…</div></div></div>`;
    return;
  }
  c.innerHTML =
    title("File Archive", actions) +
    `<div class="archive-layout"><div class="panel tree-panel"><div class="panel-head"><h3>ARCHIVE TREE</h3></div><div class="tree">${state.tree ? renderTree(state.tree) : `<div class="empty"><div class="big">🗂</div><b>Select Archive Folder</b><p>Choose the local company archive to build the Tree.</p><button class="primary" onclick="selectArchive()">Select Folder</button></div>`}</div></div><div class="panel"><div class="panel-body">${state.currentNode ? archiveContent() : '<div class="empty">Select a folder from the tree.</div>'}</div></div></div>`;
}
function archiveContent() {
  const n = state.currentNode,
    path = nodePath(n);
  let files = filterFiles(n.files);
  return `<div class="crumbs"><button onclick="selectNode('${state.tree.id}')">Home</button>${path
    .slice(1)
    .map(
      (x) =>
        `<span>›</span><button onclick="selectNode('${x.id}')">${esc(x.name)}</button>`,
    )
    .join("")}</div>
 <div class="row" style="margin-bottom:12px"><div><b>${esc(n.name)}</b><div class="muted" style="font-size:12px">${n.children.length} folders • ${n.files.length} files</div></div><div class="file-toolbar"><input placeholder="Filter this folder…" value="${esc(state.query)}" oninput="state.query=this.value;renderScreen()"><div class="view-toggle"><button class="secondary ${state.view === "list" ? "active" : ""}" onclick="state.view='list';renderScreen()">☷ List</button><button class="secondary ${state.view === "grid" ? "active" : ""}" onclick="state.view='grid';renderScreen()">▦ Grid</button></div></div></div>
 ${n.files.length || n.children.length ? `<div>${n.children.map((ch) => `<div class="file-card" style="display:flex;align-items:center;gap:12px;margin-bottom:8px;min-height:auto" onclick="selectNode('${ch.id}')"><span class="file-icon">📁</span><div><div class="file-name">${esc(ch.name)}</div><div class="file-meta">${ch.children.length} folders • ${ch.files.length} files</div></div><span style="margin-left:auto">›</span></div>`).join("")}</div>` : ""}
 ${files.length ? (state.view === "list" ? `<table class="file-table"><thead><tr><th>Name</th><th>Type</th><th>Size</th><th>Modified</th><th></th></tr></thead><tbody>${files.map(fileRow).join("")}</tbody></table>` : `<div class="grid-files">${files.map(fileCard).join("")}</div>`) : !n.children.length ? `<div class="empty"><div class="big">📭</div><b>This folder is empty.</b><p>Drag files here or create a new folder.</p></div>` : ""}
 <div class="dropzone" ondragover="event.preventDefault();this.classList.add('drag')" ondragleave="this.classList.remove('drag')" ondrop="dropFiles(event);this.classList.remove('drag')">Drag files here to upload to <b>${esc(n.name)}</b></div>`;
}
function filterFiles(files) {
  let q = state.query.toLowerCase();
  return files.filter(
    (f) =>
      (!q || f.name.toLowerCase().includes(q)) &&
      (state.filterType === "all" || ext(f.name) === state.filterType),
  );
}
function fileRow(f) {
  return `<tr><td><span style="font-size:20px">${fileIcon(f.name)}</span> <b>${esc(f.name)}</b></td><td>${esc(ext(f.name).toUpperCase() || "FILE")}</td><td>${f.size ? fmtSize(f.size) : "—"}</td><td>${f.modified ? fmtDate(f.modified) : "—"}</td><td><button class="secondary" onclick="fileMenu(event,'${f.id}')">⋯</button></td></tr>`;
}
function fileCard(f) {
  return `<div class="file-card"><div class="file-icon">${fileIcon(f.name)}</div><div class="file-name">${esc(f.name)}</div><div class="file-meta">${esc(ext(f.name).toUpperCase() || "FILE")}</div><div class="actions" style="margin-top:10px"><button class="secondary" onclick="previewFile('${f.id}')">Open</button><button class="icon-btn" onclick="fileMenu(event,'${f.id}')">⋯</button></div></div>`;
}
function findFile(n, id) {
  for (const f of n.files || []) if (f.id === id) return f;
  for (const c of n.children || []) {
    const x = findFile(c, id);
    if (x) return x;
  }
}
async function fileMenu(ev, id) {
  ev.stopPropagation();
  const f = findFile(state.tree, id);
  if (!f) return;
  const opts = [
    `<button class="secondary" onclick="previewFile('${id}')">Open / Preview</button>`,
  ];
  if (hasPermission("archive.download"))
    opts.push(
      `<button class="secondary" onclick="downloadFile('${id}')">Download</button>`,
    );
  if (hasPermission("archive.rename"))
    opts.push(
      `<button class="secondary" onclick="renameFile('${id}')">Rename</button>`,
    );
  if (hasPermission("archive.delete"))
    opts.push(
      `<button class="secondary" onclick="deleteFile('${id}')">Delete</button>`,
    );
  modal(
    `<div class="modal-head"><h3>${esc(f.name)}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div style="display:grid;gap:8px"><div><b>File Name:</b> ${esc(f.name)}</div><div><b>File Type:</b> ${esc(ext(f.name).toUpperCase() || "FILE")}</div><div><b>Location:</b> ${nodePath(
      f.parent,
    )
      .map((x) => esc(x.name))
      .join(
        " › ",
      )}</div></div><div class="actions" style="margin-top:18px">${opts.join("")}</div></div>`,
  );
}
async function previewFile(id) {
  const f = findFile(state.tree, id);
  if (!f) return;
  try {
    const file = await f.handle.getFile();
    const e = ext(f.name);
    await logAction("opened", f.name);
    if (e === "pdf") {
      const url = URL.createObjectURL(file);
      modal(
        `<div class="modal-head"><h3>${esc(f.name)}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="viewer"><iframe src="${url}"></iframe></div></div>`,
      );
    } else if (["jpg", "jpeg", "png", "gif", "webp", "svg"].includes(e)) {
      const url = URL.createObjectURL(file);
      modal(
        `<div class="modal-head"><h3>${esc(f.name)}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="viewer"><img src="${url}" alt=""></div></div>`,
      );
    } else if (["txt", "md", "csv", "json", "log"].includes(e)) {
      const text = await file.text();
      modal(
        `<div class="modal-head"><h3>${esc(f.name)}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="viewer"><pre>${esc(text)}</pre></div></div>`,
      );
    } else {
      modal(
        `<div class="modal-head"><h3>${esc(f.name)}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="empty"><div class="big">${fileIcon(f.name)}</div><b>Preview is not available for this file type.</b><div style="margin-top:14px"><button class="primary" onclick="downloadFile('${id}');closeModal()">Open File</button></div></div></div>`,
      );
    }
  } catch (e) {
    toast("File not found or access was denied", "err");
  }
}
async function downloadFile(id) {
  const f = findFile(state.tree, id);
  if (!f) return;
  try {
    const file = await f.handle.getFile();
    const a = document.createElement("a");
    a.href = URL.createObjectURL(file);
    a.download = f.name;
    a.click();
    await logAction("downloaded", f.name);
    toast("File downloaded");
  } catch (e) {
    toast("Unable to download file", "err");
  }
}
async function renameFile(id) {
  const f = findFile(state.tree, id);
  if (!f || !hasPermission("archive.rename")) return;
  const name = prompt("New file name:", f.name);
  if (!name || name === f.name) return;
  try {
    const parent = f.parent.handle;
    const data = await f.handle.getFile();
    const nh = await parent.getFileHandle(name, { create: true });
    const w = await nh.createWritable();
    await w.write(await data.arrayBuffer());
    await w.close();
    await f.handle.remove();
    await logAction("renamed", f.name + " → " + name);
    state.tree = await scanDir(state.rootHandle);
    state.currentNode =
      findNode(state.tree, state.currentNode.id) || state.tree;
    closeModal();
    renderScreen();
    toast("File renamed successfully");
  } catch (e) {
    toast(
      "Rename failed; browser permissions may prevent this operation.",
      "err",
    );
  }
}
function newFolder() {
  if (!state.currentNode || !hasPermission("archive.create")) return;
  modal(
    `<div class="modal-head"><h3>New Folder</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="field"><label>Folder Name</label><input id="newFolderName" autofocus></div></div><div class="modal-foot"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="createFolder()">Create</button></div>`,
  );
}
async function createFolder() {
  const name = $("#newFolderName").value.trim();
  if (!name) return;
  try {
    await state.currentNode.handle.getDirectoryHandle(name, { create: true });
    await logAction("created folder", name);
    state.tree = await scanDir(state.rootHandle);
    state.currentNode =
      findNode(state.tree, state.currentNode.id) || state.tree;
    closeModal();
    renderScreen();
    toast("Folder created successfully");
  } catch (e) {
    toast("Could not create folder", "err");
  }
}
async function deleteFile(id) {
  const f = findFile(state.tree, id);
  if (!f || !confirm("Delete this file? This action cannot be easily undone."))
    return;
  try {
    await f.handle.remove();
    await logAction("deleted file", f.name);
    state.tree = await scanDir(state.rootHandle);
    state.currentNode =
      findNode(state.tree, state.currentNode.id) || state.tree;
    closeModal();
    renderScreen();
    toast("File deleted");
  } catch (e) {
    toast("Delete failed", "err");
  }
}
async function dropFiles(ev) {
  ev.preventDefault();
  if (!hasPermission("archive.upload")) {
    toast("Access denied", "err");
    return;
  }
  const files = [...ev.dataTransfer.files];
  if (!files.length) return;
  try {
    for (const file of files) {
      const h = await state.currentNode.handle.getFileHandle(file.name, {
        create: true,
      });
      const w = await h.createWritable();
      await w.write(await file.arrayBuffer());
      await w.close();
      await logAction("uploaded", file.name);
    }
    state.tree = await scanDir(state.rootHandle);
    state.currentNode =
      findNode(state.tree, state.currentNode.id) || state.tree;
    renderScreen();
    toast("File upload completed");
  } catch (e) {
    toast(
      "Upload failed; grant write permission to the archive folder.",
      "err",
    );
  }
}

function searchPage(c) {
  let results = [];
  if (state.tree) collectSearch(state.tree, results);
  const q = state.query.toLowerCase();
  if (q) results = results.filter((x) => x.name.toLowerCase().includes(q));
  c.innerHTML =
    title(
      "Search",
      `<button class="secondary" onclick="state.query='';renderScreen()">Clear</button>`,
    ) +
    `<div class="panel"><div class="panel-body"><div class="file-toolbar"><input style="flex:1" id="searchBox" placeholder="Search file or folder name…" value="${esc(state.query)}" oninput="state.query=this.value;searchPage(document.getElementById('content'))"><select onchange="state.filterType=this.value;searchPage(document.getElementById('content'))"><option value="all">All Types</option><option value="pdf">PDF</option><option value="docx">Word</option><option value="xlsx">Excel</option><option value="jpg">Image</option><option value="txt">Text</option></select></div><div style="margin-top:18px">${q ? `<div class="muted" style="margin-bottom:10px">${results.length} result(s)</div>` : '<div class="empty">Enter a file or folder name to search the entire archive.</div>'}${q ? results.map((x) => `<div class="file-card" style="display:flex;align-items:center;gap:12px;margin-bottom:8px;min-height:auto"><span class="file-icon">${x.kind === "folder" ? "📁" : fileIcon(x.name)}</span><div><b>${esc(x.name)}</b><div class="file-meta">${esc(x.path)}</div></div>${x.kind === "file" ? `<button class="secondary" style="margin-left:auto" onclick="previewFile('${x.id}')">Open</button>` : ""}</div>`).join("") : ""}</div></div></div>`;
}
function collectSearch(n, a) {
  a.push({
    id: n.id,
    name: n.name,
    kind: "folder",
    path: nodePath(n)
      .map((x) => x.name)
      .join(" › "),
  });
  for (const f of n.files) {
    a.push({
      id: f.id,
      name: f.name,
      kind: "file",
      path: nodePath(f.parent)
        .map((x) => x.name)
        .join(" › "),
    });
  }
  for (const c of n.children) collectSearch(c, a);
}

function usersPage(c) {
  c.innerHTML =
    title(
      "User Management",
      `<button class="primary" onclick="openUserModal()">＋ Add User</button>`,
    ) +
    `<div class="panel"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.users.map((u) => `<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.username)}</td><td><span class="badge ${u.role}">${esc(u.role)}</span></td><td><span class="badge ${u.status}">${esc(u.status)}</span></td><td><div class="actions"><button class="secondary" onclick="openUserModal('${u.id}')">Edit</button><button class="secondary" onclick="editPermissions('${u.id}')">Permissions</button>${u.id !== state.user.id ? `<button class="secondary" onclick="toggleUser('${u.id}')">${u.status === "active" ? "Disable" : "Enable"}</button><button class="secondary" onclick="deleteUser('${u.id}')">Delete</button>` : ""}</div></td></tr>`).join("")}</tbody></table></div>`;
}
function openUserModal(id) {
  const u = id ? state.users.find((x) => x.id === id) : null;
  modal(
    `<div class="modal-head"><h3>${u ? "Edit User" : "Add User"}</h3><button class="icon-btn" onclick="closeModal()">✕</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Full Name</label><input id="uName" value="${esc(u?.name || "")}"></div><div class="field"><label>Username</label><input id="uUsername" value="${esc(u?.username || "")}" ${u ? "disabled" : ""}></div><div class="field"><label>Password ${u ? "(leave blank to keep current)" : ""}</label><input id="uPassword" type="password"></div><div class="field"><label>Confirm Password</label><input id="uConfirm" type="password"></div><div class="field"><label>Role</label><select id="uRole"><option value="user" ${u?.role === "user" ? "selected" : ""}>User</option><option value="admin" ${u?.role === "admin" ? "selected" : ""}>Admin</option></select></div><div class="field"><label>Status</label><select id="uStatus"><option value="active" ${u?.status !== "disabled" ? "selected" : ""}>Active</option><option value="disabled" ${u?.status === "disabled" ? "selected" : ""}>Disabled</option></select></div></div></div><div class="modal-foot"><button class="secondary" onclick="closeModal()">Cancel</button><button class="primary" onclick="saveUser('${id || ""}')">Save</button></div>`,
  );
}
async function saveUser(id) {
  const name = $("#uName").value.trim(),
    username = $("#uUsername").value.trim(),
    p = $("#uPassword").value,
    c = $("#uConfirm").value,
    role = $("#uRole").value,
    status = $("#uStatus").value;
  if (!name || !username || (!id && !p) || p !== c) {
    toast("Please complete the form and confirm the password", "err");
    return;
  }
  if (
    !id &&
    state.users.some((u) => u.username.toLowerCase() === username.toLowerCase())
  ) {
    toast("Username already exists", "err");
    return;
  }
  let u = id
    ? state.users.find((x) => x.id === id)
    : { id: uid("USR"), username, permissions: [...DEFAULT_PERMS] };
  u.name = name;
  u.role = role;
  u.status = status;
  if (p) u.password = p;
  if (role === "admin") u.permissions = [...PERMISSIONS];
  await put("users", u);
  state.users = await getAll("users");
  await logAction(id ? "edited user" : "created new user", u.username);
  closeModal();
  renderScreen();
  toast(id ? "User updated successfully" : "User created successfully");
}
async function toggleUser(id) {
  const u = state.users.find((x) => x.id === id);
  if (!u) return;
  u.status = u.status === "active" ? "disabled" : "active";
  await put("users", u);
  state.users = await getAll("users");
  await logAction(
    u.status === "active" ? "enabled user" : "disabled user",
    u.username,
  );
  renderScreen();
  toast("User status updated");
}
async function deleteUser(id) {
  const u = state.users.find((x) => x.id === id);
  if (!u || !confirm("Delete this user?")) return;
  await del("users", id);
  state.users = await getAll("users");
  await logAction("deleted user", u.username);
  renderScreen();
  toast("User deleted");
}

function permissionsPage(c) {
  c.innerHTML =
    title("Permissions Management") +
    `<div class="panel"><div class="panel-body"><div class="field"><label>Select User</label><select id="permUser" onchange="renderPermEditor()">${
      state.users
        .filter((u) => u.role !== "admin")
        .map(
          (u) =>
            `<option value="${u.id}">${esc(u.name)} — ${esc(u.username)}</option>`,
        )
        .join("") || "<option>No standard users</option>"
    }</select></div><div id="permEditor"></div></div></div>`;
  renderPermEditor();
}
function editPermissions(id) {
  go("permissions");
  setTimeout(() => {
    $("#permUser").value = id;
    renderPermEditor();
  }, 0);
}
function renderPermEditor() {
  const el = $("#permEditor"),
    id = $("#permUser")?.value,
    u = state.users.find((x) => x.id === id);
  if (!el || !u) return;
  const groups = {
    Dashboard: ["dashboard.view"],
    "File Archive": [
      "archive.view",
      "archive.create",
      "archive.rename",
      "archive.delete",
      "archive.upload",
      "archive.download",
      "archive.move",
    ],
    Search: ["search.view"],
    Users: ["users.view", "users.create", "users.edit", "users.delete"],
    Permissions: ["permissions.view", "permissions.edit"],
    "Activity Logs": ["logs.view"],
    Settings: ["settings.view", "settings.edit"],
    Profile: ["profile.view"],
  };
  el.innerHTML =
    Object.entries(groups)
      .map(
        ([g, ps]) =>
          `<div style="margin-top:18px"><b>${g}</b><div class="perm-grid" style="margin-top:8px">${ps.map((p) => `<label class="check"><input type="checkbox" value="${p}" ${u.permissions?.includes(p) ? "checked" : ""}> ${p.split(".")[1]}</label>`).join("")}</div></div>`,
      )
      .join("") +
    `<button class="primary" style="margin-top:20px" onclick="savePermissions('${u.id}')">Save Permissions</button>`;
}
async function savePermissions(id) {
  const u = state.users.find((x) => x.id === id);
  u.permissions = [
    ...document.querySelectorAll("#permEditor input:checked"),
  ].map((x) => x.value);
  await put("users", u);
  state.users = await getAll("users");
  await logAction("changed permissions", u.username);
  toast("Permissions updated successfully");
  renderPermEditor();
}

function logsPage(c) {
  c.innerHTML =
    title("Activity Log") +
    `<div class="panel"><table class="table"><thead><tr><th>User</th><th>Date</th><th>Time</th><th>Action</th><th>Target</th></tr></thead><tbody>${
      state.logs
        .map((l) => {
          const d = new Date(l.date);
          return `<tr><td>${esc(l.user)}</td><td>${d.toLocaleDateString()}</td><td>${d.toLocaleTimeString()}</td><td>${esc(l.action)}</td><td>${esc(l.target || "—")}</td></tr>`;
        })
        .join("") || '<tr><td colspan="5" class="empty">No activity.</td></tr>'
    }</tbody></table></div>`;
}
function settingsPage(c) {
  c.innerHTML =
    title("Settings") +
    `<div class="panel"><div class="panel-body"><div class="form-grid"><div class="field"><label>Theme</label><select onchange="state.settings.theme=this.value;saveSettings()"><option value="light" selected>Light</option></select></div><div class="field"><label>Archive</label><div class="muted" style="padding-top:11px">${state.rootHandle ? esc(state.rootHandle.name) : "Not selected"}</div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><div><b>Offline Mode</b><p class="muted">Core functionality does not require Internet. File access requires user-granted browser permission.</p></div><div class="error" style="margin-top:16px">Security note: this Phase 1 frontend-only authentication is a local prototype, not production security.</div></div></div>`;
}
function saveSettings() {
  toast("Settings saved locally");
}
function profilePage(c) {
  c.innerHTML =
    title("Profile") +
    `<div class="panel"><div class="panel-body"><div style="display:flex;gap:18px;align-items:center"><div class="avatar" style="width:70px;height:70px;font-size:28px">${esc((state.user.name || "U")[0])}</div><div><h3 style="margin:0">${esc(state.user.name)}</h3><div class="muted">${esc(state.user.username)} • ${esc(state.user.role)}</div></div></div><div class="form-grid" style="margin-top:24px"><div class="field"><label>Full Name</label><input value="${esc(state.user.name)}" disabled></div><div class="field"><label>Username</label><input value="${esc(state.user.username)}" disabled></div><div class="field"><label>Status</label><input value="${esc(state.user.status)}" disabled></div><div class="field"><label>Permissions</label><input value="${state.user.role === "admin" ? "Full Access" : (state.user.permissions || []).length + " assigned"}" disabled></div></div></div></div>`;
}

(async function boot() {
  try {
    await initDB();
    const remembered = localStorage.getItem("eg_last_user");
    loginPage();
    if (remembered) $("#loginUser").value = remembered;
  } catch (e) {
    document.body.innerHTML =
      "<div style='padding:40px;font-family:Arial'>IndexedDB is unavailable in this browser.</div>";
  }
})();
